import * as Blockly from 'blockly/core';
import 'blockly/blocks';
import * as En from 'blockly/msg/en';
import { pythonGenerator } from 'blockly/python';
import { describe, expect, it } from 'vitest';
import '@components/blockly/xrp_blocks';
import '@components/blockly/xrp_blocks_python';
import { EXAMPLES, exampleContent, suggestedExampleName } from '@/utils/examples';

/** Python generated by loading an example into a headless workspace, as the editor does. */
function pythonFor(content: string): string {
    const ws = new Blockly.Workspace();
    try {
        Blockly.serialization.workspaces.load(JSON.parse(content), ws);
        expect(ws.getAllBlocks(false).length).toBeGreaterThan(0);
        return pythonGenerator.workspaceToCode(ws);
    } finally {
        ws.dispose();
    }
}

/** Tests for the welcome screen examples. */
describe('examples', () => {
    Blockly.setLocale(En as unknown as Record<string, string>);

    it('has the four examples in order', () => {
        expect(EXAMPLES.map((e) => e.id)).toEqual([
            'driveAndTurn',
            'square',
            'avoidObstacles',
            'followLine',
        ]);
    });

    it('loads every example and generates the expected Python', () => {
        const code = Object.fromEntries(EXAMPLES.map((e) => [e.id, pythonFor(exampleContent(e))]));
        for (const source of Object.values(code)) {
            expect(source).toContain('board.wait_for_button()');
        }
        expect(code.driveAndTurn).toContain('differentialDrive.straight(30, 0.5)');
        expect(code.driveAndTurn).toContain('differentialDrive.turn(180, 0.5)');
        expect(code.square).toMatch(/for count in range\(4\):/);
        expect(code.square).toContain('differentialDrive.turn(90, 0.5)');
        expect(code.avoidObstacles).toContain('if (rangefinder.distance()) < 20:');
        expect(code.avoidObstacles).toContain('differentialDrive.set_effort(0.5, 0.5)');
        expect(code.followLine).toContain('while True:');
        expect(code.followLine).toContain(
            'if (reflectance.get_left()) > (reflectance.get_right()):',
        );
    });

    it('suggests the title, or the first free number when it is taken', () => {
        expect(suggestedExampleName('Square', '.blocks', ['robot.blocks'])).toBe('Square');
        expect(suggestedExampleName('Square', '.blocks', ['square.blocks'])).toBe('Square 2');
        expect(
            suggestedExampleName('Square', '.blocks', ['Square.blocks', 'Square 2.blocks']),
        ).toBe('Square 3');
    });
});
